import{_ as o,a0 as u,w as e,s,ao as n,I as r,x as l,a1 as p,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"使用这些去重加密工具来备份你的数据 | LCTT x X-CMD","titleTemplate":false,"description":"使用这些去重加密工具来备份你的数据 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用这些去重加密工具来备份你的数据 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用这些去重加密工具来备份你的数据 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150629 Backup with these DeDuplicating Encryption Tools","title":"使用这些去重加密工具来备份你的数据","tag":"201507","desc":""},"relativePath":"201507/20150629 Backup with these DeDuplicating Encryption Tools.md","filePath":"[post].md"}'),d={name:"201507/20150629 Backup with these DeDuplicating Encryption Tools.md"};function b(T,i,f,g,m,S){const t=u("Link");return e(),s("div",null,[i[23]||(i[23]=n('<h1 id="使用这些去重加密工具来备份你的数据" tabindex="-1">使用这些去重加密工具来备份你的数据 <a class="header-anchor" href="#使用这些去重加密工具来备份你的数据" aria-label="Permalink to “使用这些去重加密工具来备份你的数据”">​</a></h1><p>无论是体积还是价值，数据都在不断增长。快速而可靠地备份和恢复数据正变得越来越重要。社会已经适应了技术的广泛使用，并懂得了如何依靠电脑和移动设备，但很少有人能够面对丢失重要数据的现实。在遭受数据损失的公司中，30% 的公司将在一年内损失一半市值，70% 的公司将在五年内停止交易。这更加凸显了数据的价值。</p><p>随着数据在体积上的增长，提高存储利用率尤为重要。从计算机的角度说，数据去重是一种特别的数据压缩技术，因为它可以消除重复数据的拷贝，所以这个技术可以提高存储利用率。</p><p>数据并不仅仅只有其创造者感兴趣。政府、竞争者、犯罪分子、偷窥者可能都热衷于获取你的数据。他们或许想偷取你的数据，从你那里进行敲诈，或看你正在做什么。因此，对于保护你的数据，加密是非常必要的。</p><p>所以，解决方法是我们需要一个可以去重的加密备份软件。</p><p>对于所有的用户而言，做文件备份是一件非常必要的事，至今为止许多用户还没有采取足够的措施来保护他们的数据。一台电脑不论是工作在一个合作的环境中，还是供私人使用，机器的硬盘可能在没有任何警告的情况下挂掉。另外，有些数据丢失可能是人为的错误所引发的。如果没有做经常性的备份，数据也可能不可避免地丢失，即使请了专业的数据恢复公司来帮忙。</p><p>这篇文章将对 6 个去重加密备份工具进行简要的介绍。</p><h3 id="attic" tabindex="-1">Attic <a class="header-anchor" href="#attic" aria-label="Permalink to “Attic”">​</a></h3><p>Attic 是一个可用于去重、加密，验证完整性的压缩备份程序，它是用 Python 写的。Attic 的主要目标是提供一个高效且安全的方式来备份数据。Attic 使用的数据去重技术使得它适用于每日备份，因为只需存储改变的数据。</p><p>其特点有:</p><ul><li>易用</li><li>可高效利用存储空间，通过检查冗余的数据，对可变块大小的去重可以减少存储所用的空间</li><li>可选的数据加密，使用 256 位的 AES 加密算法。数据的完整性和可靠性使用 HMAC-SHA256 来校验</li><li>使用 SDSH 来进行离线备份</li><li>备份可作为文件系统来挂载</li></ul>',11)),r("p",null,[i[1]||(i[1]=l("网站: ",-1)),p(t,{href:"https://attic-backup.org/"},{default:a(()=>[...i[0]||(i[0]=[l("attic-backup.org",-1)])]),_:1})]),i[24]||(i[24]=n('<h3 id="borg" tabindex="-1">Borg <a class="header-anchor" href="#borg" aria-label="Permalink to “Borg”">​</a></h3><p>Borg 是 Attic 的一个分支。它是一个安全的开源备份程序，被设计用来高效地存储那些新的或修改过的数据。</p><p>Borg 的主要目标是提供一个高效、安全的方式来存储数据。Borg 使用的数据去重技术使得它适用于每日备份，因为只需存储改变的数据。认证加密使得它适用于存储在不完全可信的位置。</p><p>Borg 由 Python 写成。Borg 于 2015 年 5 月被创造出来，是为了解决让新的代码或重大的改变带入 Attic 的困难。</p><p>其特点包括:</p><ul><li>易用</li><li>可高效利用存储空间，通过检查冗余的数据，对可变块大小的去重被用来减少存储所用的空间</li><li>可选的数据加密，使用 256 位的 AES 加密算法。数据的完整性和可靠性使用 HMAC-SHA256 来校验</li><li>使用 SDSH 来进行离线备份</li><li>备份可作为文件系统来挂载</li></ul><p>Borg 与 Attic 不兼容。</p>',7)),r("p",null,[i[3]||(i[3]=l("网站: ",-1)),p(t,{href:"https://borgbackup.github.io/borgbackup/"},{default:a(()=>[...i[2]||(i[2]=[l("borgbackup.github.io/borgbackup",-1)])]),_:1})]),i[25]||(i[25]=n('<h3 id="obnam" tabindex="-1">Obnam <a class="header-anchor" href="#obnam" aria-label="Permalink to “Obnam”">​</a></h3><p>Obnam (OBligatory NAMe) 是一个易用、安全的基于 Python 的备份程序。备份可被存储在本地硬盘或通过 SSH SFTP 协议存储到网上。若使用了备份服务器，它并不需要任何特殊的软件，只需要使用 SSH 即可。</p><p>Obnam 通过将数据分成数据块，并单独存储它们来达到去重的目的，每次通过增量备份来生成备份，每次备份的生成就像是一次新的快照，但事实上是真正的增量备份。Obnam 由 Lars Wirzenius 开发。</p><p>其特点有:</p><ul><li>易用</li><li>快照备份</li><li>数据去重，跨文件，然后生成备份</li><li>可使用 GnuPG 来加密备份</li><li>向一个单独的仓库中备份多个客户端的数据</li><li>备份检查点 (创建一个保存点，以每 100MB 或其他容量)</li><li>包含多个选项来调整性能，包括调整 lru-size 或 upload-queue-size</li><li>支持 MD5 校验算法来识别重复的数据块</li><li>通过 SFTP 将备份存储到一个服务器上</li><li>同时支持 push(即在客户端上运行) 和 pull(即在服务器上运行)</li></ul>',5)),r("p",null,[i[5]||(i[5]=l("网站: ",-1)),p(t,{href:"http://obnam.org/"},{default:a(()=>[...i[4]||(i[4]=[l("obnam.org",-1)])]),_:1})]),i[26]||(i[26]=n('<h3 id="duplicity" tabindex="-1">Duplicity <a class="header-anchor" href="#duplicity" aria-label="Permalink to “Duplicity”">​</a></h3><p>Duplicity 以 tar 文件格式增量备份文件和目录，并使用 GnuPG 来进行加密，同时将它们上传到远程(或本地)的文件服务器上。它可以使用 ssh/scp、本地文件获取、rsync、 ftp 和 Amazon S3 等来传递数据。</p><p>因为 duplicity 使用了 librsync， 增量存档可以高效地利用存储空间，且只记录自从上次备份依赖改变的那部分文件。由于该软件使用 GnuPG 来加密或对这些归档文件进行进行签名，这使得它们免于服务器的监视或修改。</p><p>当前 duplicity 支持备份删除的文件，全部的 unix 权限，目录，符号链接， fifo 等。</p><p>duplicity 软件包还包含有 rdiffdir 工具。 Rdiffdir 是 librsync 的 rdiff 针对目录的扩展。它可以用来生成对目录的签名和差异，对普通文件也有效。</p><p>其特点有:</p><ul><li>使用简单</li><li>对归档进行加密和签名(使用 GnuPG)</li><li>高效使用带宽和存储空间，使用 rsync 的算法</li><li>标准的文件格式</li><li>可选择多种远程协议 <ul><li>本地存储</li><li>scp/ssh</li><li>ftp</li><li>rsync</li><li>HSI</li><li>WebDAV</li><li>Amazon S3</li></ul></li></ul>',7)),r("p",null,[i[7]||(i[7]=l("网站: ",-1)),p(t,{href:"http://duplicity.nongnu.org/"},{default:a(()=>[...i[6]||(i[6]=[l("duplicity.nongnu.org",-1)])]),_:1})]),i[27]||(i[27]=n('<h3 id="zbackup" tabindex="-1">ZBackup <a class="header-anchor" href="#zbackup" aria-label="Permalink to “ZBackup”">​</a></h3><p>ZBackup 是一个通用的全局去重备份工具。</p><p>其特点包括:</p><ul><li>对存储数据并行进行 LZMA 或 LZO 压缩，在一个仓库中，你还可以混合使用 LZMA 和 LZO</li><li>内置对存储数据的 AES 加密</li><li>能够删除旧的备份数据</li><li>可以使用 64 位的滚动哈希算法，使得文件冲突的数量几乎为零</li><li>仓库中存储的文件是不可修改的，已备份的文件不会被修改。</li><li>用 C++ 写成，只需少量的库文件依赖</li><li>在生成环境中可以安全使用</li><li>可以在不同仓库中进行数据交换而不必再进行压缩</li><li>使用 64 位改进型 Rabin-Karp 滚动哈希算法</li></ul>',4)),r("p",null,[i[9]||(i[9]=l("网站: ",-1)),p(t,{href:"http://zbackup.org/"},{default:a(()=>[...i[8]||(i[8]=[l("zbackup.org",-1)])]),_:1})]),i[28]||(i[28]=n('<h3 id="bup" tabindex="-1">bup <a class="header-anchor" href="#bup" aria-label="Permalink to “bup”">​</a></h3><p>bup 是一个用 Python 写的备份程序，其名称是 &quot;backup&quot; 的缩写。基于 git packfile 文件格式， bup 提供了一个高效的方式来备份一个系统，提供快速的增量备份和全局去重(在文件中或文件里，甚至包括虚拟机镜像)。</p><p>bup 在 LGPL 版本 2 协议下发行。</p><p>其特点包括:</p><ul><li>全局去重 (在文件之间或文件内部，甚至包括虚拟机镜像)</li><li>使用一个滚动的校验和算法(类似于 rsync) 来将大文件分为多个数据块</li><li>使用来自 git 的 packfile 文件格式</li><li>直接写入 packfile 文件，以此提供快速的增量备份</li><li>可以使用 &quot;par2&quot; 冗余来恢复冲突的备份</li><li>可以作为一个 FUSE 文件系统来挂载你的 bup 仓库</li></ul>',5)),r("p",null,[i[11]||(i[11]=l("网站: ",-1)),p(t,{href:"https://bup.github.io/"},{default:a(()=>[...i[10]||(i[10]=[l("bup.github.io",-1)])]),_:1})]),i[29]||(i[29]=r("hr",null,null,-1)),r("p",null,[i[13]||(i[13]=l("via: ",-1)),p(t,{href:"http://www.linuxlinks.com/article/20150628060000607/BackupTools.html"},{default:a(()=>[...i[12]||(i[12]=[l("http://www.linuxlinks.com/article/20150628060000607/BackupTools.html",-1)])]),_:1})]),r("p",null,[i[16]||(i[16]=l("译者：",-1)),p(t,{href:"https://github.com/FSSlc"},{default:a(()=>[...i[14]||(i[14]=[l("FSSlc",-1)])]),_:1}),i[17]||(i[17]=l(" 校对：",-1)),p(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[15]||(i[15]=[l("wxy",-1)])]),_:1})]),r("p",null,[i[20]||(i[20]=l("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[18]||(i[18]=[l("LCTT",-1)])]),_:1}),i[21]||(i[21]=l(" 原创翻译，",-1)),p(t,{href:"https://linux.cn/"},{default:a(()=>[...i[19]||(i[19]=[l("Linux中国",-1)])]),_:1}),i[22]||(i[22]=l(" 荣誉推出",-1))])])}const P=o(d,[["render",b]]);export{k as __pageData,P as default};
